### Use the supported Anthropic IChatClient API

**Severity:** `high`

The current provider uses SDK APIs that do not exist in Anthropic 12.43.0 (`AnthropicClientOptions`, `AsChatClient`, `CompleteAsync`, `ChatCompletion`, and `response.Message`). That blocks compilation, and the default IChatClient output limit can silently paste partial Claude responses when the API stops for length. Construct the SDK client with its init-only properties, use `AsIChatClient`/`GetResponseAsync`, dispose the client, set an explicit output budget, and report length truncation instead of returning incomplete clipboard content.

```suggestion
            using AnthropicClient client = !string.IsNullOrWhiteSpace(endpoint)
                ? new AnthropicClient { ApiKey = apiKey, BaseUrl = endpoint }
                : new AnthropicClient { ApiKey = apiKey };

            using var chatClient = client.AsIChatClient(modelId, 4096);
            var messages = new List<ChatMessage>();

            messages.Add(new ChatMessage(ChatRole.System, systemPrompt));

            if (imageBytes != null)
            {
                var contentItems = new List<AIContent>();
                if (!string.IsNullOrWhiteSpace(inputText))
                {
                    contentItems.Add(new TextContent($"Clipboard Content:\n{inputText}"));
                }

                contentItems.Add(new DataContent(imageBytes, request.ImageMimeType ?? "image/png"));
                contentItems.Add(new TextContent($"User instructions:\n{prompt}\n\nOutput:"));

                messages.Add(new ChatMessage(ChatRole.User, contentItems));
            }
            else
            {
                var userMessageContent = $"""
                    User instructions:
                    {prompt}

                    Clipboard Content:
                    {inputText}

                    Output:
                    """;
                messages.Add(new ChatMessage(ChatRole.User, userMessageContent));
            }

            var response = await chatClient.GetResponseAsync(messages, cancellationToken: cancellationToken);

            request.Usage = new AIServiceUsage((int)(response.Usage?.InputTokenCount ?? 0), (int)(response.Usage?.OutputTokenCount ?? 0));

            if (string.Equals(response.FinishReason?.Value, ChatFinishReason.Length.Value, StringComparison.Ordinal))
            {
                throw new PasteActionException(
                    "Anthropic response was truncated",
                    new InvalidOperationException("Anthropic response exceeded the configured output token limit."),
                    aiServiceMessage: "The Anthropic response was truncated. Try a shorter clipboard selection or prompt.");
            }

            return response.Text ?? string.Empty;
```
